class Solution {
    public int findMin(int[] nums) {
        int mn = nums[0];
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] < mn) mn = nums[i];
        }
        return mn;
    }
}

class Solution {
    public int findMin(int[] nums) {
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] < nums[i - 1]) return nums[i];   // 断点就是最小值
        }
        return nums[0];   // 没断点 = 未旋转
    }
}

class Solution {
    public int findMin(int[] nums) {
        int left = 0, right = nums.length - 1;

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] > nums[right]) {
                left = mid + 1;    // 在较大的左段，答案在右
            } else {
                right = mid;       // 在较小的右段，mid 可能就是答案
            }
        }
        return nums[left];
    }
}
